<?php foreach($items as $item): ?><form class="menu-edit-row" method="post" action="<?= e(url('/admin/menus/update')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><div class="menu-fields"><div><label>Ad</label><input name="label" value="<?= e($item['label']) ?>" required></div><div><label>Bağlantı</label><input name="url" value="<?= e($item['url']) ?>" required></div><div><label>Sıra</label><input type="number" name="sort_order" value="<?= (int)$item['sort_order'] ?>"></div><div><label>Konum</label><select name="location"><option value="header" <?= $item['location']==='header'?'selected':'' ?>>Üst</option><option value="footer" <?= $item['location']==='footer'?'selected':'' ?>>Alt</option></select></div><div><label>Hedef</label><select name="target"><option value="_self" <?= $item['target']==='_self'?'selected':'' ?>>Aynı sekme</option><option value="_blank" <?= $item['target']==='_blank'?'selected':'' ?>>Yeni sekme</option></select></div><div><label class="check-label"><input type="checkbox" name="is_active" <?= $item['is_active']?'checked':'' ?>> Yayında</label></div></div><div class="menu-actions"><button type="submit">Kaydet</button></form><form method="post" action="<?= e(url('/admin/menus/delete')) ?>" onsubmit="return confirm('Menü öğesi silinsin mi?');"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="button-danger" type="submit">Sil</button></form></div><?php endforeach; ?></section><?php endforeach; ?>
